namespace HardSlice.Tool;

// A solution generated by hardslice-api: its root holds the tool manifest and one .slnx, whose name is the one of its projects.
internal sealed record Solution(string Root, string Name)
{
    public const string ToolManifest = ".config/dotnet-tools.json";

    public string File => Name + ".slnx";

    public string TestProject(string suffix) => $"tests/{Name}.{suffix}/{Name}.{suffix}.csproj";

    // The root is the nearest directory that holds the manifest dotnet resolved the tool from, as global.json is resolved from it.
    public static Solution? Find(string startDirectory, TextWriter error)
    {
        var root = new DirectoryInfo(startDirectory);
        while (root is not null && !System.IO.File.Exists(Path.Combine(root.FullName, ToolManifest)))
            root = root.Parent;

        if (root is null)
        {
            error.WriteLine(
                $"error: no {ToolManifest} in '{startDirectory}' or above it: dotnet hardslice verifies a solution generated by hardslice-api, "
                + $"whose root holds it. Fix: run dotnet hardslice from that root or one of its folders. {AnalyzerVersion.Doc(ToolVersion.Current)}");
            return null;
        }

        var solutions = root.GetFiles("*.slnx");
        if (solutions.Length != 1)
        {
            error.WriteLine($"error: '{root.FullName}' holds {solutions.Length} .slnx solutions instead of one: dotnet hardslice cannot tell which one to verify.");
            return null;
        }

        return new Solution(root.FullName, Path.GetFileNameWithoutExtension(solutions[0].Name));
    }
}
